docker pull cassandra:5.0
docker run -d --name g02-cassandra -p 9042:9042 cassandra:5.0
# Cassandra braucht ~1 Minute, bis es einsatzbereit ist:
docker exec -it g02-cassandra cqlsh
# dann in der Shell:
# CREATE KEYSPACE kurse WITH replication = {'class':'SimpleStrategy','replication_factor':1};
# CREATE TABLE kurse.nachrichten (nutzer text, zeit timestamp, text text, PRIMARY KEY (nutzer, zeit));
# INSERT INTO kurse.nachrichten (nutzer, zeit, text) VALUES ('lisa', toTimestamp(now()), 'hallo');
# SELECT * FROM kurse.nachrichten WHERE nutzer='lisa';      -- ok
# SELECT * FROM kurse.nachrichten WHERE text LIKE 'hallo';  -- nicht erlaubt: warum?

docker pull cockroachdb/cockroach:latest-v24.3
docker run -d --name g05-crdb -p 26257:26257 -p 8080:8080 cockroachdb/cockroach:latest-v24.3 start-single-node --insecure
docker exec -it g05-crdb cockroach sql --insecure
# dann in der Shell:
# CREATE TABLE filme (id INT PRIMARY KEY, titel STRING, jahr INT);
# INSERT INTO filme VALUES (1,'Matrix',1999), (2,'Inception',2010);
# EXPLAIN SELECT titel FROM filme WHERE jahr = 1999;
# EXPLAIN SELECT * FROM filme WHERE titel = 'Matrix';
# Web-UI: http://localhost:8080  (im Insecure-Modus ohne Anmeldung zugänglich, nur ansehen)

docker pull clickhouse/clickhouse-server:24.8
docker run -d --name g07-ch -p 8123:8123 --ulimit nofile=262144:262144 clickhouse/clickhouse-server:24.8
docker exec -it g07-ch clickhouse-client
# dann in der Shell:
# CREATE TABLE filme (id UInt32, titel String, jahr UInt16) ENGINE = MergeTree ORDER BY jahr;
# INSERT INTO filme SELECT number, 'Film ' || number, 1950 + (number % 70) FROM numbers(1000000);
# EXPLAIN SELECT count(*) FROM filme WHERE jahr = 1999;         -- Plan zeigt: es werden nur Granules mit jahr=1999 gelesen
# SELECT count(*) FROM filme WHERE jahr = 1999;
# Vergleich: gleiche Tabelle ORDER BY id und die Abfrage nochmal

docker pull alpine:3.20
docker run -it --rm -v "$(pwd)":/data alpine:3.20 sh
# dann im Container:
# apk add sqlite
# sqlite3 /data/demo.db
# .dbinfo
# CREATE TABLE filme (id INTEGER PRIMARY KEY, titel TEXT);
# INSERT INTO filme (titel) VALUES ('Matrix'), ('Inception');
# EXPLAIN QUERY PLAN SELECT * FROM filme WHERE titel='Matrix';
# ANALYZE;
# EXPLAIN QUERY PLAN SELECT * FROM filme WHERE titel='Matrix';  -- was hat sich geaendert?

docker pull mysql:8
docker run -d --name g09-mysql -e MYSQL_ROOT_PASSWORD=dbi5 -p 3306:3306 mysql:8
# Startup dauert ~30 Sekunden:
docker exec -it g09-mysql mysql -uroot -pdbi5
# dann in der Shell:
# CREATE DATABASE d; USE d;
# CREATE TABLE filme (id INT PRIMARY KEY, titel VARCHAR(40), KEY (titel));
# INSERT INTO filme VALUES (1,'Matrix'), (2,'Inception');
# EXPLAIN FORMAT=TREE SELECT * FROM filme WHERE titel='Matrix';
# EXPLAIN FORMAT=TREE SELECT id FROM filme WHERE titel LIKE 'M%';  -- covering index?

docker pull mariadb:10.11
docker run -d --name g10-maria -e MARIADB_ROOT_PASSWORD=dbi5 mariadb:10.11
docker exec -it g10-maria mariadb -uroot -pdbi5
# dann in der Shell:
# INSTALL SONAME 'ha_rocksdb';
# CREATE DATABASE d; USE d;
# CREATE TABLE films_innodb (id INT PRIMARY KEY, titel VARCHAR(40)) ENGINE=INNODB;
# CREATE TABLE films_myrocks (id INT PRIMARY KEY, titel VARCHAR(40)) ENGINE=ROCKSDB;
# INSERT INTO films_innodb WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n < 100000) SELECT n, CONCAT('F', n) FROM seq;
# INSERT INTO films_myrocks SELECT id, titel FROM films_innodb;
# in zweitem Terminal: docker exec -it g10-maria ls -la /var/lib/mysql/d/
#  -> Wo liegen .ibd-Dateien, wo SST-Dateien (.sst)?

docker pull pgvector/pgvector:pg17
docker run -d --name g11-pg -e POSTGRES_PASSWORD=dbi5 -p 5432:5432 pgvector/pgvector:pg17
docker exec -it g11-pg psql -U postgres
# dann in der Shell:
# CREATE EXTENSION vector;
# CREATE TABLE eintraege (id serial PRIMARY KEY, embedding vector(3));
# INSERT INTO eintraege (embedding) SELECT ('[' || random() || ',' || random() || ',' || random() || ']')::vector FROM generate_series(1,100000);
# CREATE INDEX ON eintraege USING hnsw (embedding vector_cosine_ops);
# EXPLAIN ANALYZE SELECT id FROM eintraege ORDER BY embedding <=> '[0.5,0.5,0.5]' LIMIT 5;
